import{z as s,x as d,o as t,c as B,q as n,j as l,D as e,d as i,s as A,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SMAWK 决策单调","description":"","frontmatter":{"title":"SMAWK 决策单调","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/smawk.md","filePath":"cs/smawk.md","lastUpdated":1791063341000}'),p={name:"cs/smawk.md"};function m(c,a,h,D,M,S){const r=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=n('<h1 id="smawk-决策单调" tabindex="-1">SMAWK 决策单调 <a class="header-anchor" href="#smawk-决策单调" aria-label="Permalink to &quot;SMAWK 决策单调&quot;">​</a></h1><div class="epigraph"><p>完全单调矩阵每行最小值的列号非降；SMAWK 用减治在 $O(n)$ 次查询内找出所有行最小（列数同类）。</p><footer>—— 据 Aggarwal, Klawe, Moran, Shor and Wilber, Geometric Applications of a Matrix-Searching Algorithm, 1987 整理</footer></div><p>上一课<a href="/cs/dc-opt-quadrangle">分治优化与四边形不等式</a>用 \\(opt\\) 单调做分治，做到 \\(O(n\\log n)\\)。本课再进一步：当矩阵 \\(A[i,j]=dp[j]+w(j,i)\\) 完全单调时，SMAWK 能以线性次数的查询求出每行的 \\(\\arg\\min\\)。缺口是这份减治怎么工作，不是再证一遍四边形不等式。后课插头 DP 换到网格轮廓线上的指数状态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完全单调的定义：对 \\(a\\lt b\\)、\\(c\\lt d\\)，若 \\(M(a,c)\\gt M(a,d)\\)，则 \\(M(b,c)\\gt M(b,d)\\)——上一行里 \\(d\\) 列已经更好，更靠下的行 \\(d\\) 只会更好，行最小位置因此非降。SMAWK 的减治：只保留奇数行，在更小的矩阵上递归求出它们的最小列；先比较并删去不可能成为任何奇数行最小的「劣列」，列数随之减少，再把偶数行的答案夹在相邻奇数行答案之间线性补齐。查询 \\(M(i,j)\\) 若 \\(O(1)\\)，\\(n\\times n\\) 矩阵总时间 \\(O(n)\\)。</p><p>用在一层 DP 上：\\(dp&#39;[i]=\\min_j dp[j]+w(j,i)\\) 的每个 \\(i\\) 正好对应矩阵一行的最小值，一次 SMAWK 全部求出，比分治优化少一个 \\(\\log\\)。</p><p><span class="marginnote">术语翻译：把一层转移 \\(dp&#39;[i]=\\min_j(dp[j]+w(j,i))\\) 排成矩阵 \\(M[i,j]=dp[j]+w(j,i)\\)，「求转移」就变成「逐行找最小值」这件事。\\(n\\) 行 \\(n\\) 列逐格扫要 \\(n^2\\) 次比较，完全单调保证只看 \\(O(n)\\) 次格子就够——省下的正是那 \\(n^2\\to n\\)。</span></p><h3 id="不是任意单调队列" tabindex="-1">不是任意单调队列 <a class="header-anchor" href="#不是任意单调队列" aria-label="Permalink to &quot;不是任意单调队列&quot;">​</a></h3><p>完全单调是逐元素传递的条件，强于「每行最小非降」这条使用性质，且实现细节多，删列与递归的次序都影响正确性。不会证 \\(w\\) 使矩阵完全单调，就不要宣称用了 SMAWK；实践中分治优化已够用。</p><p><span class="marginnote">Aggarwal 等 1987，作者姓首字母即 SMAWK。后课插头 DP 是另一套指数状态压缩，不是矩阵搜索问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>使用次序固定：先证 \\(w\\) 使 \\(M\\) 完全单调，再调用 SMAWK 得每行 \\(opt[i]\\)，最后按 \\(opt[i]\\) 填 \\(dp\\)。实现上可先写对分治版，SMAWK 只当加速叠上去——结构证不出时，分治版仍是正确答案。</p>',12)),(t(),l(o,null,{default:e(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%AE%8C%E5%85%A8%E5%8D%95%E8%B0%83%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20SM%5B%22SMAWK%20%E5%87%8F%E6%B2%BB%22%5D%0A%20%20SM%20--%3E%20OPT%5B%22%E6%AF%8F%E8%A1%8C%20argmin%22%5D%0A%20%20OPT%20--%3E%20DP%5B%22%E4%B8%80%E5%B1%82%20DP%20%E7%BA%BF%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"查询 \\(M(i,j)\\) 的代价要乘进总时间：不是 \\(O(1)\\) 时（例如还需二分），线性承诺随之失效。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"减列是核心：把相邻奇数行在各列的值比较一遍，凡在所有奇数行上都不占优的列，永远不会成为奇数行的最小，删去后矩阵变瘦，递归规模减半。与四边形不等式的关系：四边形常能推出完全单调，但细节依赖 \\(w\\) 的形状，二者不能混同。与 CHT 对照：凸壳技巧要转移项有直线结构，SMAWK 只要矩阵单调，适用面更宽，验证也更重。",-1)),(t(),l(o,null,{default:e(()=>[A(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8F%AA%E4%BF%9D%E7%95%99%E5%A5%87%E6%95%B0%E8%A1%8C%20%E9%80%92%E5%BD%92%E6%B1%82%E5%AE%83%E4%BB%AC%E7%9A%84%E6%9C%80%E5%B0%8F%E5%88%97%22%5D%20--%3E%20B%5B%22%E7%94%A8%E6%A0%88%E9%80%90%E5%88%97%E6%A3%80%E6%9F%A5%E5%90%84%E5%88%97%22%5D%0A%20%20B%20--%3E%20C%7B%22%E8%AF%A5%E5%88%97%E5%9C%A8%E6%9F%90%E4%B8%AA%E5%A5%87%E6%95%B0%E8%A1%8C%E4%B8%8A%E6%9B%B4%E4%BC%98%3F%22%7D%0A%20%20C%20--%20%22%E6%98%AF%22%20--%3E%20D%5B%22%E7%95%99%E5%9C%A8%E6%A0%88%E9%87%8C%22%5D%0A%20%20C%20--%20%22%E5%90%A6%22%20--%3E%20E%5B%22%E5%BC%B9%E6%A0%88%E5%88%A0%E5%8E%BB%E8%BF%99%E4%B8%80%E5%88%97%22%5D%0A%20%20E%20--%3E%20B%0A%20%20D%20--%3E%20F%5B%22%E7%98%A6%E7%9F%A9%E9%98%B5%E7%BB%A7%E7%BB%AD%E9%80%92%E5%BD%92%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%81%B6%E6%95%B0%E8%A1%8C%E7%AD%94%E6%A1%88%E5%A4%B9%E5%9C%A8%E7%9B%B8%E9%82%BB%E5%A5%87%E6%95%B0%E8%A1%8C%E4%B9%8B%E9%97%B4%20%E7%BA%BF%E6%80%A7%E8%A1%A5%E9%BD%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：\\(n=16\\) 时奇数行只剩 8 行，第一轮删列后列数往往压到 10 列以内，下一层递归就是 \\(8\\times10\\) 的瘦矩阵；每层开销线性，层数 \\(\\log_2 16=4\\)，总查询量约 \\(16+8+\\cdots\\) 这个等比级数，量级仍是 \\(O(n)\\)——不是不查询，而是让矩阵自己越查越小。</span></p><p><span class="marginnote">常见误区：以为「决策单调（每行 \\(\\arg\\min\\) 非降）」就等于「完全单调」。前者是要用的结果，后者是逐格传递的更强前提——上半格某列更优，下半格这个优势必须保持。只有前者证不出后者，就不能宣称 SMAWK，退回分治优化即可。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不手写 SMAWK 全伪代码，也不写高维推广。后课默认：决策单调先上分治优化，证得完全单调才升级 SMAWK。下一课插头 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完全单调保证所有行最小可线性求出。</li><li>一层 DP 的转移可压到线性次查询，比分治少一个 \\(\\log\\)。</li><li>结构要求比分治优化更苛刻，证不出就退回分治。</li><li>出处：Aggarwal, Klawe, Moran, Shor and Wilber, 1987。</li></ul>',6))])}const _=s(p,[["render",m]]);export{u as __pageData,_ as default};
